export const BANK_VERSION='atlas-1.0';
export const GROUPS={emotional:'정서 반응',social:'사회적 에너지',openness:'경험과 생각의 개방성',cooperation:'관계와 협력',execution:'실행과 자기조절',talent:'재능에 대한 자기관찰',metacognition:'판단과 문제 해결'};
export const DOMAINS={logic:'논리 추론',quantitative:'수리 추론',spatial:'공간 추론',verbal:'언어 추론',causal:'인과 추론',calibration:'확률적 판단'};
export function freshState(previous=null){return{schemaVersion:1,bankVersion:BANK_VERSION,startedAt:new Date().toISOString(),updatedAt:new Date().toISOString(),answers:{},taskAnswers:{},taskConfidence:{},taskSubmitted:false,challenges:{},evidence:{},context:{},previous};}
export function facetScore(facet,answers){const entries=facet.items.filter(i=>Number.isInteger(answers[i.id])&&answers[i.id]>=1&&answers[i.id]<=7).map(i=>({item:i,raw:answers[i.id],keyed:i.reverse?8-answers[i.id]:answers[i.id]}));const n=entries.length;const mean=n?entries.reduce((s,x)=>s+x.keyed,0)/n:null;const minimum=Math.ceil(facet.items.length*.75);return{id:facet.id,label:facet.label,group:facet.group,n,total:facet.items.length,minimum,coverage:n/facet.items.length,mean,score:n>=minimum?Math.round((mean-1)/6*100):null,unknown:facet.items.filter(i=>answers[i.id]===0).length,entries};}
export function scoreFacets(facets,state){return facets.map(f=>facetScore(f,state.answers));}
export function taskSummary(tasks,state){const details=tasks.filter(t=>Number.isInteger(state.taskAnswers[t.id])).map(t=>({id:t.id,domain:t.domain,correct:state.taskAnswers[t.id]===t.correct,confidence:Number.isFinite(state.taskConfidence[t.id])?state.taskConfidence[t.id]/100:null}));const calibrated=details.filter(x=>x.confidence!==null);return{n:details.length,total:tasks.length,correct:details.filter(x=>x.correct).length,domains:Object.keys(DOMAINS).map(d=>{const subset=details.filter(x=>x.domain===d);return{id:d,n:subset.length,total:tasks.filter(t=>t.domain===d).length,correct:subset.filter(x=>x.correct).length};}),confidenceN:calibrated.length,meanConfidence:calibrated.length?calibrated.reduce((s,x)=>s+x.confidence,0)/calibrated.length:null,calibrationAccuracy:calibrated.length?calibrated.filter(x=>x.correct).length/calibrated.length:null,brier:calibrated.length?calibrated.reduce((s,x)=>s+(x.confidence-Number(x.correct))**2,0)/calibrated.length:null,details};}
export function qualitySummary(state,checks){const attentions=checks.filter(c=>c.expected!==undefined&&Number.isInteger(state.answers[c.id])&&state.answers[c.id]>0);const pairs=checks.filter(c=>c.original&&state.answers[c.id]>=1&&state.answers[c.original]>=1).map(c=>({original:c.original,repeat:c.id,delta:Math.abs(state.answers[c.id]-state.answers[c.original])}));const vals=Object.entries(state.answers).filter(([id,v])=>!id.startsWith('check_')&&v>=1).map(([,v])=>v);const counts=Array(8).fill(0);vals.forEach(v=>counts[v]++);return{attentionN:attentions.length,attentionMismatch:attentions.filter(c=>state.answers[c.id]!==c.expected).length,pairN:pairs.length,meanPairDifference:pairs.length?pairs.reduce((s,p)=>s+p.delta,0)/pairs.length:null,largePairDifferences:pairs.filter(p=>p.delta>=3).length,mostUsed:vals.length?Math.max(...counts)/vals.length:null};}
export function buildChecks(facets){const chosen=[0,7,12,18,24,30,38,45].filter(i=>facets[i]);return[...chosen.map((idx,j)=>({id:'check_repeat_'+j,text:facets[idx].items[0].text,original:facets[idx].items[0].id})),...[[3,'이 문항은 내용이 아니라 응답 표시를 확인합니다. 3을 선택해 주세요.'],[5,'잠깐 쉬어가며 표시를 확인합니다. 이 문항에서는 5를 선택해 주세요.'],[2,'응답 점검 문항입니다. 이 문항에서는 2를 선택해 주세요.'],[6,'마지막 표시 확인 문항입니다. 여기서는 6을 선택해 주세요.']].map(([expected,text],j)=>({id:'check_attention_'+j,text,expected}))];}
export function snapshot(facets,tasks,state){return{date:state.updatedAt,facets:scoreFacets(facets,state).map(({id,n,score})=>({id,n,score})),tasks:state.taskSubmitted?taskSummary(tasks,state):null,context:state.context};}
export function validateImport(raw,facets,tasks,challenges,checks){if(!raw||raw.schemaVersion!==1||raw.bankVersion!==BANK_VERSION)throw new Error('이 검사 버전의 답변 파일이 아닙니다.');const out=freshState();const itemIds=new Set([...facets.flatMap(f=>f.items.map(i=>i.id)),...checks.map(i=>i.id)]);for(const[id,v]of Object.entries(raw.answers||{})){if(!itemIds.has(id)||!Number.isInteger(v)||v<0||v>7)throw new Error('문항 또는 응답 값이 올바르지 않습니다.');out.answers[id]=v;}const taskIds=new Set(tasks.map(t=>t.id));for(const[id,v]of Object.entries(raw.taskAnswers||{})){if(!taskIds.has(id)||!Number.isInteger(v)||v<0||v>3)throw new Error('수행 응답이 올바르지 않습니다.');out.taskAnswers[id]=v;}for(const[id,v]of Object.entries(raw.taskConfidence||{})){if(!taskIds.has(id)||!Number.isFinite(v)||v<0||v>100)throw new Error('확신도 값이 올바르지 않습니다.');out.taskConfidence[id]=v;}for(const id of ['sleep','fatigue','distraction','opportunity']){if(typeof raw.context?.[id]==='string')out.context[id]=raw.context[id].slice(0,100);}const evidenceKeys=['spatial','quantitative','verbal','systems','creative','social','diary'];for(const key of evidenceKeys){if(typeof raw.evidence?.[key]==='string')out.evidence[key]=raw.evidence[key].slice(0,30000);}for(const challenge of challenges){const r=raw.challenges?.[challenge.id];if(!r)continue;if(typeof r.text!=='string')throw new Error('난제 답변 형식이 올바르지 않습니다.');out.challenges[challenge.id]={text:r.text.slice(0,30000),ratings:{}};for(const[k,v]of Object.entries(r.ratings||{})){if(!Number.isInteger(+k)||+k<0||+k>=challenge.rubric.length||!Number.isInteger(v)||v<0||v>4)throw new Error('평가 기준 값이 올바르지 않습니다.');out.challenges[challenge.id].ratings[k]=v;}}
out.taskSubmitted=raw.taskSubmitted===true;out.startedAt=typeof raw.startedAt==='string'&&!Number.isNaN(Date.parse(raw.startedAt))?raw.startedAt:out.startedAt;out.updatedAt=new Date().toISOString();if(raw.previous&&Array.isArray(raw.previous.facets)){out.previous={date:typeof raw.previous.date==='string'?raw.previous.date:'이전 회차',facets:raw.previous.facets.filter(f=>facets.some(x=>x.id===f.id)&&Number.isInteger(f.n)&&f.n>=0&&f.n<=8&&(f.score===null||Number.isFinite(f.score)&&f.score>=0&&f.score<=100)).map(f=>({id:f.id,n:f.n,score:f.score}))};}return out;}
